Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ubifs: Fix wrong orphan node deletion in
 ubifs_jnl_update|rename

There a wrong orphan node deleting in error handling path in
ubifs_jnl_update() and ubifs_jnl_rename(), which may cause
following error msg:

  UBIFS error (ubi0:0 pid 1522): ubifs_delete_orphan [ubifs]:
  missing orphan ino 65

Fix this by checking whether the node has been operated for
adding to orphan list before being deleted,

Signed-off-by: Zhihao Cheng <chengzhihao1@huawei.com>
Fixes: 823838a486888cf484e ("ubifs: Add hashes to the tree node cache")
Signed-off-by: Richard Weinberger <richard@nod.at>

Here is the root cause:
The bug arises from the incorrect deletion of orphan nodes in the error handling paths of the `ubifs_jnl_update` and `ubifs_jnl_rename` functions. Specifically, orphan nodes were being deleted without confirming whether they had been added to the orphan list, leading to potential errors indicating missing orphan inodes.

Here is the patch:
  */
 int ubifs_jnl_update(struct ubifs_info *c, const struct inode *dir,
 		     const struct fscrypt_name *nm, const struct inode *inode,
 		     int deletion, int xent)
 {
-	int err, dlen, ilen, len, lnum, ino_offs, dent_offs;
+	int err, dlen, ilen, len, lnum, ino_offs, dent_offs, orphan_added = 0;
 	int aligned_dlen, aligned_ilen, sync = IS_DIRSYNC(dir);
 	int last_reference = !!(deletion && inode->i_nlink == 0);
 	struct ubifs_inode *ui = ubifs_inode(inode);
 	struct ubifs_inode *host_ui = ubifs_inode(dir);
 	struct ubifs_dent_node *dent;
 	struct ubifs_ino_node *ino;
 	union ubifs_key dent_key, ino_key;
 	u8 hash_dent[UBIFS_HASH_ARR_SZ];
 	u8 hash_ino[UBIFS_HASH_ARR_SZ];
 	u8 hash_ino_host[UBIFS_HASH_ARR_SZ];

 	ubifs_assert(c, mutex_is_locked(&host_ui->ui_mutex));

 	dlen = UBIFS_DENT_NODE_SZ + fname_len(nm) + 1;
 	ilen = UBIFS_INO_NODE_SZ;

 	/*
 	 * If the last reference to the inode is being deleted, then there is
 	 * no need to attach and write inode data, it is being deleted anyway.
 	 * And if the inode is being deleted, no need to synchronize
 	 * write-buffer even if the inode is synchronous.
 	 */
 	if (!last_reference) {
 		ilen += ui->data_len;
 		sync |= IS_SYNC(inode);
 	}

 	aligned_dlen = ALIGN(dlen, 8);
 	aligned_ilen = ALIGN(ilen, 8);

 	len = aligned_dlen + aligned_ilen + UBIFS_INO_NODE_SZ;
 	/* Make sure to also account for extended attributes */
 	if (ubifs_authenticated(c))
 		len += ALIGN(host_ui->data_len, 8) + ubifs_auth_node_sz(c);
 	else
 		len += host_ui->data_len;

 	dent = kzalloc(len, GFP_NOFS);
 	if (!dent)
 		return -ENOMEM;

 	/* Make reservation before allocating sequence numbers */
 	err = make_reservation(c, BASEHD, len);
 	if (err)
 		goto out_free;

 	if (!xent) {
 		dent->ch.node_type = UBIFS_DENT_NODE;
 		if (fname_name(nm) == NULL)
 			dent_key_init_hash(c, &dent_key, dir->i_ino, nm->hash);
 		else
 			dent_key_init(c, &dent_key, dir->i_ino, nm);
 	} else {
 		dent->ch.node_type = UBIFS_XENT_NODE;
 		xent_key_init(c, &dent_key, dir->i_ino, nm);
 	}

 	key_write(c, &dent_key, dent->key);
 	dent->inum = deletion ? 0 : cpu_to_le64(inode->i_ino);
 	dent->type = get_dent_type(inode->i_mode);
 	dent->nlen = cpu_to_le16(fname_len(nm));
 	memcpy(dent->name, fname_name(nm), fname_len(nm));
 	dent->name[fname_len(nm)] = '\0';
 	set_dent_cookie(c, dent);

 	zero_dent_node_unused(dent);
 	ubifs_prep_grp_node(c, dent, dlen, 0);
 	err = ubifs_node_calc_hash(c, dent, hash_dent);
 	if (err)
 		goto out_release;

 	ino = (void *)dent + aligned_dlen;
 	pack_inode(c, ino, inode, 0);
 	err = ubifs_node_calc_hash(c, ino, hash_ino);
 	if (err)
 		goto out_release;

 	ino = (void *)ino + aligned_ilen;
 	pack_inode(c, ino, dir, 1);
 	err = ubifs_node_calc_hash(c, ino, hash_ino_host);
 	if (err)
 		goto out_release;

 	if (last_reference) {
 		err = ubifs_add_orphan(c, inode->i_ino);
 		if (err) {
 			release_head(c, BASEHD);
 			goto out_finish;
 		}
 		ui->del_cmtno = c->cmt_no;
+		orphan_added = 1;
 	}

 	err = write_head(c, BASEHD, dent, len, &lnum, &dent_offs, sync);
 	if (err)
 		goto out_release;
 	if (!sync) {
 		struct ubifs_wbuf *wbuf = &c->jheads[BASEHD].wbuf;

 		ubifs_wbuf_add_ino_nolock(wbuf, inode->i_ino);
 		ubifs_wbuf_add_ino_nolock(wbuf, dir->i_ino);
 	}
 	release_head(c, BASEHD);
 	kfree(dent);
 	ubifs_add_auth_dirt(c, lnum);

 	if (deletion) {
 		if (fname_name(nm) == NULL)
 			err = ubifs_tnc_remove_dh(c, &dent_key, nm->minor_hash);
 		else
 			err = ubifs_tnc_remove_nm(c, &dent_key, nm);
 		if (err)
 			goto out_ro;
 		err = ubifs_add_dirt(c, lnum, dlen);
 	} else
 		err = ubifs_tnc_add_nm(c, &dent_key, lnum, dent_offs, dlen,
 				       hash_dent, nm);
 	if (err)
 		goto out_ro;

 	/*
 	 * Note, we do not remove the inode from TNC even if the last reference
 	 * to it has just been deleted, because the inode may still be opened.
 	 * Instead, the inode has been added to orphan lists and the orphan
 	 * subsystem will take further care about it.
 	 */
 	ino_key_init(c, &ino_key, inode->i_ino);
 	ino_offs = dent_offs + aligned_dlen;
 	err = ubifs_tnc_add(c, &ino_key, lnum, ino_offs, ilen, hash_ino);
 	if (err)
 		goto out_ro;

 	ino_key_init(c, &ino_key, dir->i_ino);
 	ino_offs += aligned_ilen;
 	err = ubifs_tnc_add(c, &ino_key, lnum, ino_offs,
 			    UBIFS_INO_NODE_SZ + host_ui->data_len, hash_ino_host);
 	if (err)
 		goto out_ro;

 	finish_reservation(c);
 	spin_lock(&ui->ui_lock);
 	ui->synced_i_size = ui->ui_size;
 	spin_unlock(&ui->ui_lock);
 	if (xent) {
 		spin_lock(&host_ui->ui_lock);
 		host_ui->synced_i_size = host_ui->ui_size;
 		spin_unlock(&host_ui->ui_lock);
 	}
 	mark_inode_clean(c, ui);
 	mark_inode_clean(c, host_ui);
 	return 0;

 out_finish:
 	finish_reservation(c);
 out_free:
 	kfree(dent);
 	return err;

 out_release:
 	release_head(c, BASEHD);
 	kfree(dent);
 out_ro:
 	ubifs_ro_mode(c, err);
-	if (last_reference)
+	if (orphan_added)
 		ubifs_delete_orphan(c, inode->i_ino);
 	finish_reservation(c);
 	return err;
 }

  */
 int ubifs_jnl_rename(struct ubifs_info *c, const struct inode *old_dir,
 		     const struct inode *old_inode,
 		     const struct fscrypt_name *old_nm,
 		     const struct inode *new_dir,
 		     const struct inode *new_inode,
 		     const struct fscrypt_name *new_nm,
 		     const struct inode *whiteout, int sync)
 {
 	void *p;
 	union ubifs_key key;
 	struct ubifs_dent_node *dent, *dent2;
-	int err, dlen1, dlen2, ilen, lnum, offs, len;
+	int err, dlen1, dlen2, ilen, lnum, offs, len, orphan_added = 0;
 	int aligned_dlen1, aligned_dlen2, plen = UBIFS_INO_NODE_SZ;
 	int last_reference = !!(new_inode && new_inode->i_nlink == 0);
 	int move = (old_dir != new_dir);
 	struct ubifs_inode *uninitialized_var(new_ui);
 	u8 hash_old_dir[UBIFS_HASH_ARR_SZ];
 	u8 hash_new_dir[UBIFS_HASH_ARR_SZ];
 	u8 hash_new_inode[UBIFS_HASH_ARR_SZ];
 	u8 hash_dent1[UBIFS_HASH_ARR_SZ];
 	u8 hash_dent2[UBIFS_HASH_ARR_SZ];

 	ubifs_assert(c, ubifs_inode(old_dir)->data_len == 0);
 	ubifs_assert(c, ubifs_inode(new_dir)->data_len == 0);
 	ubifs_assert(c, mutex_is_locked(&ubifs_inode(old_dir)->ui_mutex));
 	ubifs_assert(c, mutex_is_locked(&ubifs_inode(new_dir)->ui_mutex));

 	dlen1 = UBIFS_DENT_NODE_SZ + fname_len(new_nm) + 1;
 	dlen2 = UBIFS_DENT_NODE_SZ + fname_len(old_nm) + 1;
 	if (new_inode) {
 		new_ui = ubifs_inode(new_inode);
 		ubifs_assert(c, mutex_is_locked(&new_ui->ui_mutex));
 		ilen = UBIFS_INO_NODE_SZ;
 		if (!last_reference)
 			ilen += new_ui->data_len;
 	} else
 		ilen = 0;

 	aligned_dlen1 = ALIGN(dlen1, 8);
 	aligned_dlen2 = ALIGN(dlen2, 8);
 	len = aligned_dlen1 + aligned_dlen2 + ALIGN(ilen, 8) + ALIGN(plen, 8);
 	if (move)
 		len += plen;

 	len += ubifs_auth_node_sz(c);

 	dent = kzalloc(len, GFP_NOFS);
 	if (!dent)
 		return -ENOMEM;

 	/* Make reservation before allocating sequence numbers */
 	err = make_reservation(c, BASEHD, len);
 	if (err)
 		goto out_free;

 	/* Make new dent */
 	dent->ch.node_type = UBIFS_DENT_NODE;
 	dent_key_init_flash(c, &dent->key, new_dir->i_ino, new_nm);
 	dent->inum = cpu_to_le64(old_inode->i_ino);
 	dent->type = get_dent_type(old_inode->i_mode);
 	dent->nlen = cpu_to_le16(fname_len(new_nm));
 	memcpy(dent->name, fname_name(new_nm), fname_len(new_nm));
 	dent->name[fname_len(new_nm)] = '\0';
 	set_dent_cookie(c, dent);
 	zero_dent_node_unused(dent);
 	ubifs_prep_grp_node(c, dent, dlen1, 0);
 	err = ubifs_node_calc_hash(c, dent, hash_dent1);
 	if (err)
 		goto out_release;

 	dent2 = (void *)dent + aligned_dlen1;
 	dent2->ch.node_type = UBIFS_DENT_NODE;
 	dent_key_init_flash(c, &dent2->key, old_dir->i_ino, old_nm);

 	if (whiteout) {
 		dent2->inum = cpu_to_le64(whiteout->i_ino);
 		dent2->type = get_dent_type(whiteout->i_mode);
 	} else {
 		/* Make deletion dent */
 		dent2->inum = 0;
 		dent2->type = DT_UNKNOWN;
 	}
 	dent2->nlen = cpu_to_le16(fname_len(old_nm));
 	memcpy(dent2->name, fname_name(old_nm), fname_len(old_nm));
 	dent2->name[fname_len(old_nm)] = '\0';
 	set_dent_cookie(c, dent2);
 	zero_dent_node_unused(dent2);
 	ubifs_prep_grp_node(c, dent2, dlen2, 0);
 	err = ubifs_node_calc_hash(c, dent2, hash_dent2);
 	if (err)
 		goto out_release;

 	p = (void *)dent2 + aligned_dlen2;
 	if (new_inode) {
 		pack_inode(c, p, new_inode, 0);
 		err = ubifs_node_calc_hash(c, p, hash_new_inode);
 		if (err)
 			goto out_release;

 		p += ALIGN(ilen, 8);
 	}

 	if (!move) {
 		pack_inode(c, p, old_dir, 1);
 		err = ubifs_node_calc_hash(c, p, hash_old_dir);
 		if (err)
 			goto out_release;
 	} else {
 		pack_inode(c, p, old_dir, 0);
 		err = ubifs_node_calc_hash(c, p, hash_old_dir);
 		if (err)
 			goto out_release;

 		p += ALIGN(plen, 8);
 		pack_inode(c, p, new_dir, 1);
 		err = ubifs_node_calc_hash(c, p, hash_new_dir);
 		if (err)
 			goto out_release;
 	}

 	if (last_reference) {
 		err = ubifs_add_orphan(c, new_inode->i_ino);
 		if (err) {
 			release_head(c, BASEHD);
 			goto out_finish;
 		}
 		new_ui->del_cmtno = c->cmt_no;
+		orphan_added = 1;
 	}

 	err = write_head(c, BASEHD, dent, len, &lnum, &offs, sync);
 	if (err)
 		goto out_release;
 	if (!sync) {
 		struct ubifs_wbuf *wbuf = &c->jheads[BASEHD].wbuf;

 		ubifs_wbuf_add_ino_nolock(wbuf, new_dir->i_ino);
 		ubifs_wbuf_add_ino_nolock(wbuf, old_dir->i_ino);
 		if (new_inode)
 			ubifs_wbuf_add_ino_nolock(&c->jheads[BASEHD].wbuf,
 						  new_inode->i_ino);
 	}
 	release_head(c, BASEHD);

 	ubifs_add_auth_dirt(c, lnum);

 	dent_key_init(c, &key, new_dir->i_ino, new_nm);
 	err = ubifs_tnc_add_nm(c, &key, lnum, offs, dlen1, hash_dent1, new_nm);
 	if (err)
 		goto out_ro;

 	offs += aligned_dlen1;
 	if (whiteout) {
 		dent_key_init(c, &key, old_dir->i_ino, old_nm);
 		err = ubifs_tnc_add_nm(c, &key, lnum, offs, dlen2, hash_dent2, old_nm);
 		if (err)
 			goto out_ro;

 		ubifs_delete_orphan(c, whiteout->i_ino);
 	} else {
 		err = ubifs_add_dirt(c, lnum, dlen2);
 		if (err)
 			goto out_ro;

 		dent_key_init(c, &key, old_dir->i_ino, old_nm);
 		err = ubifs_tnc_remove_nm(c, &key, old_nm);
 		if (err)
 			goto out_ro;
 	}

 	offs += aligned_dlen2;
 	if (new_inode) {
 		ino_key_init(c, &key, new_inode->i_ino);
 		err = ubifs_tnc_add(c, &key, lnum, offs, ilen, hash_new_inode);
 		if (err)
 			goto out_ro;
 		offs += ALIGN(ilen, 8);
 	}

 	ino_key_init(c, &key, old_dir->i_ino);
 	err = ubifs_tnc_add(c, &key, lnum, offs, plen, hash_old_dir);
 	if (err)
 		goto out_ro;

 	if (move) {
 		offs += ALIGN(plen, 8);
 		ino_key_init(c, &key, new_dir->i_ino);
 		err = ubifs_tnc_add(c, &key, lnum, offs, plen, hash_new_dir);
 		if (err)
 			goto out_ro;
 	}

 	finish_reservation(c);
 	if (new_inode) {
 		mark_inode_clean(c, new_ui);
 		spin_lock(&new_ui->ui_lock);
 		new_ui->synced_i_size = new_ui->ui_size;
 		spin_unlock(&new_ui->ui_lock);
 	}
 	mark_inode_clean(c, ubifs_inode(old_dir));
 	if (move)
 		mark_inode_clean(c, ubifs_inode(new_dir));
 	kfree(dent);
 	return 0;

 out_release:
 	release_head(c, BASEHD);
 out_ro:
 	ubifs_ro_mode(c, err);
-	if (last_reference)
+	if (orphan_added)
 		ubifs_delete_orphan(c, new_inode->i_ino);
 out_finish:
 	finish_reservation(c);
 out_free:
 	kfree(dent);
 	return err;
 }



